function resetTimestampMilliseconds(agent, resetsAt) {
    if (typeof resetsAt !== 'number' || !Number.isFinite(resetsAt)) return null;
    if (agent === 'codex' && resetsAt < UNIX_MILLISECONDS_THRESHOLD) return resetsAt * 1000;

